        "returns": "len",
        "writes_out": false
      }
    },
    {
      "id": "IO",
      "type": "IO",
      "text": "Returns VERA_ERR when len == 0.",
      "asserted_values": ["0xFFFFFFFFFFFFFFFF"],
      "confidence": 1.0,
      "io": {
        "when": "len == 0",
        "returns": "VERA_ERR",
        "writes_out": false
      }
    },
    {
      "id": "SIDE",
      "type": "SIDE",
      "text": "Does not write to out.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "CF",
      "type": "CF",
      "text": "Iterates over each byte in the input data.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "CF",
      "type": "CF",
      "text": "Performs a loop for each bit in the current byte.",
      "asserted_values": [],
      "confidence": 1.0
    }
  ],
  "recovered_c": "uint64_t fn_01(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len == 0) {\n    return VERA_ERR;\n  }\n  uint32_t h = 0xffffffff;\n  for (size_t i = 0; i < len; i++) {\n    h = h ^ in[i];\n    for (uint8_t b = 0; b < 8; b++) {\n      h = -(h & 1) & 0xedb88320 ^ h >> 1;\n    }\n  }\n  return (uint64_t)~h;\n}"
}
